<?php
namespace ServSys\PreventiveMaintenance;
use ServSys\Customers\CustomerRepository;
use ServSys\Sites\SiteRepository;
use ServSys\Equipment\EquipmentRepository;
if(!defined('ABSPATH')){exit;}
final class PMAgreementService {
 private $agreements;private $covered;private $customers;private $sites;private $equipment;private $plans;private $terms;
 public function __construct(){ $this->agreements=new PMAgreementRepository();$this->covered=new PMAgreementEquipmentRepository();$this->customers=new CustomerRepository();$this->sites=new SiteRepository();$this->equipment=new EquipmentRepository();$this->plans=new PMPlanRepository();$this->terms=new PMPlanTermRepository();}
 public function save(array $data,int $id=0): int {$customer_id=absint($data['customer_id']??0);$site_id=absint($data['site_id']??0);$plan_id=absint($data['pm_plan_id']??0);$term_months=absint($data['term_months']??0);$customer=$this->customers->find($customer_id);$site=$this->sites->find($site_id);$plan=$this->plans->find($plan_id);if(!$customer){throw new \InvalidArgumentException('Customer does not belong to the current company.');}if(!$site||(int)$site['customer_id']!==$customer_id){throw new \InvalidArgumentException('Site must belong to the selected Customer and current company.');}if(!$plan){throw new \InvalidArgumentException('PM Plan does not belong to the current company.');}$term=null;foreach($this->terms->for_plan($plan_id) as $candidate){if((int)$candidate['term_months']===$term_months){$term=$candidate;break;}}if(!$term){throw new \InvalidArgumentException('Selected PM Plan term is invalid.');}$start=$this->date($data['start_date']??'','Start date');$end=$this->date($data['end_date']??'','End date');if($end<$start){throw new \InvalidArgumentException('End date cannot precede start date.');}$agreement_date=!empty($data['agreement_date'])?$this->date($data['agreement_date'],'Agreement date'):null;$visits=absint($data['visits_per_year']??0);$status=sanitize_key($data['status']??'active');if(!in_array($status,array('active','expired','cancelled'),true)){throw new \InvalidArgumentException('Invalid PM Agreement status.');}$clean=array('customer_id'=>$customer_id,'site_id'=>$site_id,'pm_plan_id'=>$plan_id,'agreement_date'=>$agreement_date,'start_date'=>$start,'end_date'=>$end,'term_months'=>$term_months,'contract_price'=>(float)$term['price'],'plan_description_snapshot'=>$plan['description'],'plan_tm_estimate_snapshot'=>(float)$plan['tm_estimate'],'visits_per_year'=>$visits,'additional_services'=>sanitize_textarea_field($data['additional_services']??''),'notes'=>sanitize_textarea_field($data['notes']??''),'status'=>$status,'updated_at'=>current_time('mysql',true),'updated_by'=>get_current_user_id()?:null);if($id){if(!$this->agreements->find($id)){throw new \InvalidArgumentException('PM Agreement does not belong to the current company.');}if(!$this->agreements->update($id,$clean)){throw new \RuntimeException('Unable to save PM Agreement.');}return $id;}$clean['created_at']=$clean['updated_at'];$clean['created_by']=$clean['updated_by'];$id=$this->agreements->create($clean);if(!$id){throw new \RuntimeException('Unable to create PM Agreement.');}return $id;}
 public function replace_equipment(int $agreement_id,array $equipment_ids): void {$agreement=$this->agreements->find($agreement_id);if(!$agreement){throw new \InvalidArgumentException('PM Agreement does not belong to the current company.');}$valid=array();foreach(array_unique(array_map('absint',$equipment_ids)) as $equipment_id){if(!$equipment_id){continue;}$item=$this->equipment->find($equipment_id);if(!$item||(int)$item['site_id']!==(int)$agreement['site_id']||(int)$item['customer_id']!==(int)$agreement['customer_id']){throw new \InvalidArgumentException('Covered Equipment must belong to the Agreement Site and Customer.');}$valid[]=$equipment_id;}$wpdb=$GLOBALS['wpdb'];/* phpcs:ignore WordPress.DB.DirectDatabaseQuery.DirectQuery, WordPress.DB.DirectDatabaseQuery.NoCaching -- Covered equipment replacement must be atomic. */$wpdb->query('START TRANSACTION');try{if(!$this->covered->delete_for_agreement($agreement_id)){throw new \RuntimeException('Unable to replace covered equipment.');}$now=current_time('mysql',true);$user=get_current_user_id();foreach($valid as $equipment_id){if(!$this->covered->create(array('pm_agreement_id'=>$agreement_id,'equipment_id'=>$equipment_id,'created_at'=>$now,'created_by'=>$user?:null))){throw new \RuntimeException('Unable to save covered equipment.');}}/* phpcs:ignore WordPress.DB.DirectDatabaseQuery.DirectQuery, WordPress.DB.DirectDatabaseQuery.NoCaching -- Covered equipment replacement must be atomic. */$wpdb->query('COMMIT');}catch(\Throwable $e){/* phpcs:ignore WordPress.DB.DirectDatabaseQuery.DirectQuery, WordPress.DB.DirectDatabaseQuery.NoCaching -- Roll back partial covered equipment replacement. */$wpdb->query('ROLLBACK');throw $e;}}
 private function date(string $value,string $label): string {$d=\DateTimeImmutable::createFromFormat('!Y-m-d',$value);if(!$d||$d->format('Y-m-d')!==$value){throw new \InvalidArgumentException('Date is invalid.');}return $value;}
}
